nginx.nginx.conf:
user nginx;
worker_processes auto;
pid /opt/e1-native/pids/nginx.pid;
error_log /opt/e1-native/logs/nginx-main.log crit;
events { worker_connections 1024; }
http {
include /opt/e1-native/nginx-image/etc/nginx/mime.types;
default_type application/octet-stream;
sendfile on;
keepalive_timeout 65;
include /opt/e1-native/nginx/default.conf;
}

nginx.default.conf:
map $uri $course_upstream {
    default "";
    ~^/api/v1/(auth|users)/ 127.0.0.1:18081;
    ~^/api/v1/(files|directories)(/|$) 127.0.0.1:18082;
    /api/v1/quota 127.0.0.1:18082;
    ~^/api/v1/shares(/|$) 127.0.0.1:18083;
    ~^/api/v1/s/ 127.0.0.1:18083;
}

# Never log request URI, query, body or authorization: share tokens are capabilities.
log_format course '$request_id $request_method status=$status duration=$request_time upstream=$upstream_status';

server {
    listen 127.0.0.1:18080;
    server_name _;
    root /opt/e1-native/nginx-image/usr/share/nginx/html;
    access_log /opt/e1-native/logs/access.log course;
    error_log /opt/e1-native/logs/error.log crit;
    client_max_body_size 105m;
    add_header Referrer-Policy no-referrer always;
    add_header X-Content-Type-Options nosniff always;

    location = /healthz { access_log off; default_type text/plain; return 200 'UP\n'; }
    location = /api { return 404; }
    location ^~ /internal { return 404; }
    location ^~ /health { return 404; }

    location = /api/v1/files {
        include /opt/e1-native/nginx/course-proxy.conf;
        proxy_read_timeout 120s;
        proxy_request_buffering off;
        proxy_buffering off;
    }

    location ~ ^/api/v1/(files/[0-9]+/download|s/[^/]+/download)$ {
        include /opt/e1-native/nginx/course-proxy.conf;
        proxy_read_timeout 120s;
        proxy_buffering off;
    }

    location /api/ {
        include /opt/e1-native/nginx/course-proxy.conf;
        proxy_read_timeout 15s;
    }

    location / { try_files $uri $uri/ /index.html; }
}

nginx.course-proxy.conf:
if ($course_upstream = "") { return 404; }
proxy_pass http://$course_upstream;
proxy_http_version 1.1;
proxy_set_header Connection "";
proxy_set_header Host $host;
proxy_set_header Authorization $http_authorization;
proxy_set_header X-Request-Id $request_id;
proxy_connect_timeout 3s;
proxy_send_timeout 120s;
